import { SimWorld } from '/Users/wesner/Workspace/minorincident/.claude/worktrees/s86-weaponpower/src/sim/world/SimWorld.ts';
const ids=['bat','fire-axe','handgun','army-mg','shotgun','rocket-launcher','pipe-bomb','hunting-rifle','nail-gun','machete','molotov','assault-rifle','flashbang','flamethrower'];
const targets=[['ordinary',60,'infected.runner',false],['sprinter',45,'infected.sprinter',false],['alpha',300,'infected.alpha',false],['brute',450,'infected.brute',false],['armored-front',240,'infected.armored',true],['armored-rear',240,'infected.armored',false]] as const;
for(const name of ids)for(const [target,hp,archetype,front] of targets){const w=new SimWorld();await w.init();w.loadScenario('combat-arena',1);const action='weapon.'+name;w.combat!.setLoadout([action],['weapon.fire-axe']);w.combat!.assist.setting='Off';const range=name==='rocket-launcher'?10:1.5;const id=w.spawnDummy('infected.dummy',{x:range,z:0},{hp});const e=w.entities.get(id)!;e.archetype=archetype;if(archetype==='infected.alpha'||archetype==='infected.armored')e.infected={...(e.infected??{}),...(archetype==='infected.alpha'?{alphaType:'standard'}:{special:'armor'})} as any;e.transform.yaw=front?Math.PI:0;let shots=0;w.events.on('combat.attack',e=>{if(e.type==='combat.attack'&&e.sourceId===1)shots++;});let ticks=0;for(;ticks<1800&&e.health.current>0;ticks++){e.transform.x=range;e.transform.z=0;w.clearInput();w.setInput({aim:{x:1,z:0},aimPoint:{x:range,z:0},left:{down:['pipe-bomb','molotov','flashbang'].includes(name)?ticks%15===0:ticks===0,held:true,up:false}});w.update();}console.log(JSON.stringify({weapon:name,target,initialHp:hp,seconds:ticks/60,attacks:shots,hp:e.health.current,killed:e.health.current===0}));w.dispose();}

